// Illustrations explain the displayed word; unillustrated ideas use language in context.
// The drawing is never used during independent recognition or listening questions.
const WORD_SCENES={大海:'sea',海浪:'waves',沙子:'sand',贝壳:'shell',小船:'boat',高山:'mountain',小河:'river',木头:'wood',大树:'tree',树林:'grove',森林:'forest',树叶:'leaf',小草:'grass',花朵:'flower',开花:'flower',种子:'seed',发芽:'sprout',泥土:'soil',树根:'roots',下雨:'rain',小雨:'rain',雪花:'snow',白云:'cloud',天空:'sky',太阳:'sun',阳光:'sunshine',月亮:'moon',日出:'sunrise',星星:'stars',晴天:'sun',小鱼:'fish',小鸟:'bird',小猫:'cat',兔子:'rabbit',鸭子:'duck',小鸡:'chick',大象:'elephant',汽车:'car',飞机:'plane',书本:'book',本子:'notebook',铅笔:'pencil',白纸:'paper',台灯:'lamp',电灯:'lamp',房子:'house',开门:'door',门口:'door',书包:'bag',衣服:'shirt',鞋子:'shoe',小床:'bed',小桥:'bridge',小路:'path',田地:'field',石头:'stone',火苗:'flame',中间:'middle',草地:'grass',西瓜:'watermelon',大米:'rice',面条:'noodles',水果:'fruit',绿色:'green',蓝色:'blue',黄色:'yellow',红色:'red',白色:'white',黑色:'black',圆形:'circle',方形:'square',左边:'left',右边:'right',上面:'up',下面:'down',二月:'february',六点:'sixoclock',一个:'count1',三个:'count3',五个:'count5',九个:'count9',十个:'count10'};
const ACTION_PROMPTS={吃:'做一做吃饭的动作，再说：“我在吃饭。”',喝:'拿起自己的水杯，说：“我在喝水。”',听:'闭上眼睛，听听现在有什么声音。',看:'找一找，你现在能看到什么？',走:'站起来，慢慢走两步。',跑:'想一想：走路和跑步，哪一个更快？',跳:'在安全、空旷的地方轻轻跳一下。',坐:'找把椅子坐下，说：“我坐下了。”',站:'从椅子上站起来，再说：“我站起来了。”',笑:'对爸爸妈妈笑一笑。',哭:'说一说：伤心的时候，怎样请大人帮忙？',爱:'说一说：你爱家里的谁？',好:'说说今天发生的一件好事。',给:'把手边的小物品递给大人，说：“这个给你。”',帮:'今天你想给爸爸妈妈帮什么忙？',洗:'想一想，吃饭前为什么要洗手？',远:'看看窗外，再找一个远处的东西。',近:'找一个靠近自己的东西。',快:'用手指演示：小兔快快跑。',慢:'用手指演示：小蜗牛慢慢爬。',轻:'拿起一张纸，感觉它有多轻。',重:'请大人帮忙，比较一下纸和书哪个重。'};
function markedWord(x){return [...x.word].map(c=>c===x.char?`<mark>${esc(c)}</mark>`:esc(c)).join('')}
function sceneKind(x){return WORD_SCENES[x.word]||null}
function semanticVisual(x){const kind=sceneKind(x);if(!kind)return `<div class="meaning-context"><span class="meaning-label">在词语里认识它</span><div class="meaning-word">${markedWord(x)}</div><p>${esc(ACTION_PROMPTS[x.char]||x.sentence||'和爸爸妈妈一起，用这个字说一个生活里的词语。')}</p></div>`;return `<figure class="meaning-picture"><svg viewBox="0 0 300 150" role="img" aria-label="${esc(x.word)}的示意图"><use href="illustrations.svg#${kind}"></use></svg><figcaption>画面里的词语：<strong>${esc(x.word)}</strong></figcaption></figure>`}
